<?php
require_once __DIR__ . '/auth.php';

$stmt = $conn->prepare('SELECT * FROM employees WHERE id=? LIMIT 1');
$stmt->bind_param('i', $employeeId); $stmt->execute(); $employee = $stmt->get_result()->fetch_assoc();
if (!$employee) die('Employee account not found.');

$today = date('Y-m-d');
$monthStart = date('Y-m-01');
$monthEnd = date('Y-m-t');

$att = $conn->prepare("SELECT SUM(status='Present') present_count, SUM(status='Absent') absent_count, SUM(status='Late') late_count, COALESCE(SUM(total_hours),0) total_hours FROM attendance WHERE employee_id=? AND attendance_date BETWEEN ? AND ?");
$att->bind_param('iss', $employeeId, $monthStart, $monthEnd); $att->execute(); $summary = $att->get_result()->fetch_assoc();
$todayStmt = $conn->prepare('SELECT * FROM attendance WHERE employee_id=? AND attendance_date=? LIMIT 1');
$todayStmt->bind_param('is', $employeeId, $today); $todayStmt->execute(); $todayAtt = $todayStmt->get_result()->fetch_assoc();

$schedStmt = $conn->prepare("SELECT * FROM work_schedules WHERE employee_id=? AND status='Active' AND effective_from<=? AND (effective_until IS NULL OR effective_until>=?) ORDER BY effective_from DESC, id DESC LIMIT 1");
$schedStmt->bind_param('iss', $employeeId, $today, $today); $schedStmt->execute(); $schedule = $schedStmt->get_result()->fetch_assoc();

$leaveStmt = $conn->prepare("SELECT COUNT(*) c FROM leave_requests WHERE employee_id=? AND status='Approved' AND date_until>=? AND date_from<=?");
$leaveStmt->bind_param('iss', $employeeId, $today, $today); $leaveStmt->execute(); $leaveToday = (int)$leaveStmt->get_result()->fetch_assoc()['c'];

$reqStmt = $conn->prepare("SELECT request_type, request_date, details, status FROM request_history WHERE employee_id=? ORDER BY request_date DESC LIMIT 5");
$reqStmt->bind_param('i', $employeeId); $reqStmt->execute(); $requests = $reqStmt->get_result()->fetch_all(MYSQLI_ASSOC);

$payStmt = $conn->prepare('SELECT payroll_period_start, payroll_period_end, net_pay FROM payslips WHERE employee_id=? ORDER BY payroll_period_end DESC, id DESC LIMIT 1');
$payStmt->bind_param('i', $employeeId); $payStmt->execute(); $latestPay = $payStmt->get_result()->fetch_assoc();
function time12($v){ return $v ? date('g:i A', strtotime($v)) : '--'; }
?>
