<body><div class="admin-shell"><div class="sidebar-backdrop" data-sidebar-close></div><aside class="admin-sidebar" id="adminSidebar"><div class="sidebar-header"><a class="brand-mark" href="index.php"><span class="brand-icon"><i class="bi bi-grid-1x2-fill"></i></span><span class="brand-copy"><span class="brand-title">WFMS Employee</span><span class="brand-subtitle">Workforce Management</span></span></a></div><nav class="sidebar-nav"><a class="nav-link active" href="index.php"><span class="nav-icon"><i class="bi bi-speedometer2"></i></span><span class="nav-text">Dashboard</span></a><a class="nav-link" href="timesheet.php"><span class="nav-icon"><i class="bi bi-clock-history"></i></span><span class="nav-text">Time Sheet</span></a><a class="nav-link" href="attendance.php"><span class="nav-icon"><i class="bi bi-calendar-check"></i></span><span class="nav-text">Attendance Record</span></a><a class="nav-link" href="request.php"><span class="nav-icon"><i class="bi bi-send"></i></span><span class="nav-text">Requests</span></a><a class="nav-link" href="payslip.php"><span class="nav-icon"><i class="bi bi-receipt"></i></span><span class="nav-text">Payslip</span></a><a class="nav-link" href="profile.php"><span class="nav-icon"><i class="bi bi-person-badge"></i></span><span class="nav-text">Profile</span></a></nav><div class="sidebar-footer"><span class="status-dot"></span><span class="sidebar-footer-text">System running smoothly</span></div></aside><div class="admin-main"><nav class="navbar admin-navbar navbar-expand bg-white"><div class="container-fluid px-3 px-lg-4"><button class="sidebar-toggle" type="button" data-sidebar-toggle><span></span><span></span><span></span></button><div class="navbar-actions ms-auto"><button class="icon-button theme-toggle" type="button" data-theme-toggle><i class="bi bi-moon-stars" data-theme-icon></i></button><div class="dropdown"><button class="profile-button dropdown-toggle" data-bs-toggle="dropdown"><img class="avatar-img avatar-sm" src="../assets/images/avatar/avatar.jpg" alt="User"><span class="profile-name d-none d-sm-inline"><?php echo e($employee['full_name']); ?></span></button><ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item" href="profile.php">Profile</a></li><li><hr class="dropdown-divider"></li><li><a class="dropdown-item" href="logout.php">Sign out</a></li></ul></div></div></div></nav>
<main class="dashboard-content"><div class="container-fluid px-3 px-lg-4 py-4"><div class="page-heading"><div><h1 class="h3 mb-1">Dashboard</h1><p class="text-muted mb-0">Your personal work status, schedule, requests, and payroll summary.</p></div></div>
<section class="row g-3"><div class="col-12 col-sm-6 col-xl-3"><div class="panel h-100 p-4"><div class="text-muted small">TODAY</div><div class="fs-4 fw-semibold mt-2"><?php echo $todayAtt ? e(ucfirst($todayAtt['status'])) : 'No Record'; ?></div><div class="text-muted small mt-1"><?php echo $todayAtt ? time12($todayAtt['time_in']) . ' - ' . time12($todayAtt['time_out']) : 'Time in to start your day'; ?></div></div></div><div class="col-12 col-sm-6 col-xl-3"><div class="panel h-100 p-4"><div class="text-muted small">MONTHLY HOURS</div><div class="fs-4 fw-semibold mt-2"><?php echo number_format((float)$summary['total_hours'], 2); ?> h</div><div class="text-muted small mt-1">Total recorded hours</div></div></div><div class="col-12 col-sm-6 col-xl-3"><div class="panel h-100 p-4"><div class="text-muted small">LEAVE TODAY</div><div class="fs-4 fw-semibold mt-2"><?php echo $leaveToday ? 'On Leave' : 'Not on Leave'; ?></div><div class="text-muted small mt-1"><?php echo $leaveToday ? 'Approved leave' : 'Regular workday'; ?></div></div></div><div class="col-12 col-sm-6 col-xl-3"><div class="panel h-100 p-4"><div class="text-muted small">LATEST NET PAY</div><div class="fs-4 fw-semibold mt-2">₱<?php echo $latestPay ? number_format((float)$latestPay['net_pay'],2) : '0.00'; ?></div><div class="text-muted small mt-1"><?php echo $latestPay ? e(date('M j, Y', strtotime($latestPay['payroll_period_end']))) : 'No payslip yet'; ?></div></div></div></section>
<section class="row g-3 mt-1"><div class="col-12 col-xl-7"><div class="panel h-100"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-clock-history"></i><span>Today's Attendance</span></h2><p class="text-muted mb-0">Your attendance record for today.</p></div><a class="btn btn-light btn-sm" href="attendance.php">View Details</a></div><div class="p-4"><div class="row text-center"><div class="col-4"><div class="text-muted small">Time In</div><div class="fs-5 fw-semibold mt-1"><?php echo $todayAtt ? time12($todayAtt['time_in']) : '--'; ?></div></div><div class="col-4"><div class="text-muted small">Time Out</div><div class="fs-5 fw-semibold mt-1"><?php echo $todayAtt ? time12($todayAtt['time_out']) : '--'; ?></div></div><div class="col-4"><div class="text-muted small">Hours</div><div class="fs-5 fw-semibold mt-1"><?php echo $todayAtt ? number_format((float)$todayAtt['total_hours'],2) . ' h' : '0.00 h'; ?></div></div></div><div class="row text-center mt-4"><div class="col-4"><div class="text-muted small">Present</div><div class="fs-4 fw-semibold text-success"><?php echo (int)$summary['present_count']; ?></div></div><div class="col-4"><div class="text-muted small">Absent</div><div class="fs-4 fw-semibold text-danger"><?php echo (int)$summary['absent_count']; ?></div></div><div class="col-4"><div class="text-muted small">Late</div><div class="fs-4 fw-semibold text-warning"><?php echo (int)$summary['late_count']; ?></div></div></div></div></div></div><div class="col-12 col-xl-5"><div class="panel h-100"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-calendar3"></i><span>Today's Schedule</span></h2><p class="text-muted mb-0">Your active work schedule.</p></div><a class="btn btn-light btn-sm" href="request.php">Request Change</a></div><div class="p-4"><?php if($schedule): ?><div class="mb-3"><div class="text-muted small">Shift</div><div class="fw-semibold mt-1"><?php echo e(ucfirst($schedule['shift'])); ?> Shift</div></div><div class="mb-3"><div class="text-muted small">Schedule</div><div class="fw-semibold mt-1"><?php echo e($schedule['schedule_days']); ?></div></div><div><div class="text-muted small">Time</div><div class="fw-semibold mt-1"><?php echo time12($schedule['start_time']); ?> - <?php echo time12($schedule['end_time']); ?></div></div><?php else: ?><p class="text-muted mb-0">No active schedule has been assigned yet.</p><?php endif; ?></div></div></div></section>
<section class="row g-3 mt-1"><div class="col-12 col-xl-7"><div class="panel"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-send"></i><span>Recent Requests</span></h2><p class="text-muted mb-0">Latest leave and shift requests.</p></div><a class="btn btn-light btn-sm" href="request.php">View All</a></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Type</th><th>Date</th><th>Details</th><th>Status</th></tr></thead><tbody><?php if(!$requests): ?><tr><td colspan="4" class="text-center text-muted py-4">No requests yet.</td></tr><?php else: foreach($requests as $r): ?><tr><td><?php echo e($r['request_type']); ?></td><td><?php echo e(date('M j, Y', strtotime($r['request_date']))); ?></td><td class="small"><?php echo e($r['details']); ?></td><td><span class="badge <?php echo $r['status']==='Approved'?'bg-success':($r['status']==='Rejected'?'bg-danger':'bg-warning text-dark'); ?>"><?php echo e($r['status']); ?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div><div class="col-12 col-xl-5"><div class="panel h-100"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-receipt"></i><span>Latest Payslip</span></h2><p class="text-muted mb-0">Your most recent payroll record.</p></div><a class="btn btn-light btn-sm" href="payslip.php">View Payslip</a></div><div class="p-4"><?php if($latestPay): ?><div class="mb-3"><div class="text-muted small">Payroll Period</div><div class="fw-semibold mt-1"><?php echo e(date('M j, Y',strtotime($latestPay['payroll_period_start']))); ?> - <?php echo e(date('M j, Y',strtotime($latestPay['payroll_period_end']))); ?></div></div><div><div class="text-muted small">Net Pay</div><div class="fs-3 fw-semibold mt-1">₱<?php echo number_format((float)$latestPay['net_pay'],2); ?></div></div><?php else: ?><p class="text-muted mb-0">No payslip has been released yet.</p><?php endif; ?></div></div></div></section>
</div></main></div></div><script src="../assets/js/bootstrap.bundle.min.js"></script><script src="../assets/js/main.js"></script></body></html>